SELECT data->'commit'->>'collection' AS event, COUNT(*) AS count FROM {TABLE} GROUP BY event ORDER BY count DESC;
SELECT data->'commit'->>'collection' AS event, COUNT(*) AS count, COUNT(DISTINCT data->>'did') AS users FROM {TABLE} WHERE data->>'kind' = 'commit' AND data->'commit'->>'operation' = 'create' GROUP BY event ORDER BY count DESC;
SELECT data->'commit'->>'collection' AS event, EXTRACT(HOUR FROM CAST(CAST(data->>'time_us' AS INT64) AS TIMESTAMP[us])) AS hour_of_day, COUNT(*) AS count FROM {TABLE} WHERE data->>'kind' = 'commit' AND data->'commit'->>'operation' = 'create' AND data->'commit'->>'collection' IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT data->>'did' AS user_id, CAST(MIN(CAST(data->>'time_us' AS INT64)) AS TIMESTAMP[us]) AS first_post_ts FROM {TABLE} WHERE data->>'kind' = 'commit' AND data->'commit'->>'operation' = 'create' AND data->'commit'->>'collection' = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT data->>'did' AS user_id, CAST((MAX(CAST(data->>'time_us' AS INT64)) - MIN(CAST(data->>'time_us' AS INT64))) / 1000 AS INTEGER) AS activity_span FROM {TABLE} WHERE data->>'kind' = 'commit' AND data->'commit'->>'operation' = 'create' AND data->'commit'->>'collection' = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
